<?php

declare(strict_types=1);

require_once __DIR__ . '/Database.php';
require_once __DIR__ . '/Auth.php';
require_once __DIR__ . '/AppNavigation.php';
require_once __DIR__ . '/AccessPolicy.php';
require_once __DIR__ . '/ProductionContext.php';

final class VolunteerShiftManagementExperience
{
    private const ROUTES=['/admin/volunteer-shifts','/admin/volunteer-shifts/new','/admin/volunteer-shifts/view'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user)self::redirect(($basePath?:'').'/login');if(!AccessPolicy::canManageVolunteers($user))self::forbidden($basePath,$user);$_SESSION['volunteer_shift_admin_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$route,$basePath,$user);
        $production=ProductionContext::selected($db,$user);$productionId=$production?(int)$production['id']:0;$requirements=self::requirements($db);$shift=null;if($route==='/admin/volunteer-shifts/view'){$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$shift=self::shift($db,(int)$id,$productionId);}self::page($db,$route,$basePath,$user,$production,$requirements,$shift);
    }

    private static function handlePost(PDO $db,string $route,string $basePath,array $user):never
    {
        if(!hash_equals((string)($_SESSION['volunteer_shift_admin_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired. Please try again.');self::redirect($basePath.'/admin/volunteer-shifts');}
        $action=(string)($_POST['action']??'');try{
            if($action==='create'){$id=self::saveShift($db,$user,0,$_POST);self::flash('success','Volunteer shift created in the selected production.');self::redirect($basePath.'/admin/volunteer-shifts/view?id='.$id);}
            if($action==='update'){$id=(int)(filter_input(INPUT_POST,'shift_id',FILTER_VALIDATE_INT)?:0);self::saveShift($db,$user,$id,$_POST);self::flash('success','Volunteer shift updated.');self::redirect($basePath.'/admin/volunteer-shifts/view?id='.$id);}
            if($action==='roster_status'){$signupId=(int)(filter_input(INPUT_POST,'signup_id',FILTER_VALIDATE_INT)?:0);$shiftId=(int)(filter_input(INPUT_POST,'shift_id',FILTER_VALIDATE_INT)?:0);self::updateRosterStatus($db,$user,$signupId,$shiftId,(string)($_POST['status']??''));self::flash('success','Volunteer roster status updated.');self::redirect($basePath.'/admin/volunteer-shifts/view?id='.$shiftId);}
            throw new RuntimeException('Choose a valid volunteer operation.');
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());$shiftId=filter_input(INPUT_POST,'shift_id',FILTER_VALIDATE_INT)?:0;$fallback=$route==='/admin/volunteer-shifts/new'?'/admin/volunteer-shifts/new':($shiftId?'/admin/volunteer-shifts/view?id='.(int)$shiftId:'/admin/volunteer-shifts');self::redirect($basePath.$fallback);}
    }

    private static function saveShift(PDO $db,array $actor,int $shiftId,array $input):int
    {
        $production=ProductionContext::selected($db,$actor);if(!$production)throw new RuntimeException('Select an active production before creating or editing volunteer shifts.');
        $title=trim((string)($input['title']??''));$category=trim((string)($input['category']??''));$location=trim((string)($input['location']??''));$startsAt=self::parseLocalDateTime((string)($input['starts_at']??''),'Start time');$endsAt=self::parseLocalDateTime((string)($input['ends_at']??''),'End time');$requiredSlots=filter_var($input['required_slots']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>500]])?:0;$approvalRequired=isset($input['approval_required'])?1:0;$requirements=array_values(array_unique(array_filter(array_map('intval',(array)($input['requirement_ids']??[])),static fn(int $id):bool=>$id>0)));
        if($title===''||mb_strlen($title)>190)throw new RuntimeException('Enter a shift title no longer than 190 characters.');if($category===''||mb_strlen($category)>100)throw new RuntimeException('Enter a category no longer than 100 characters.');if($location===''||mb_strlen($location)>190)throw new RuntimeException('Enter a location no longer than 190 characters.');if($endsAt<=$startsAt)throw new RuntimeException('The shift end time must be after the start time.');if($requiredSlots<1)throw new RuntimeException('Enter at least one required volunteer slot.');
        if($requirements){$placeholders=implode(',',array_fill(0,count($requirements),'?'));$check=$db->prepare("SELECT id FROM volunteer_requirements WHERE id IN ($placeholders)");$check->execute($requirements);if(count($check->fetchAll(PDO::FETCH_COLUMN))!==count($requirements))throw new RuntimeException('One or more selected requirements no longer exist.');}
        $db->beginTransaction();try{$before=null;if($shiftId>0){$s=$db->prepare('SELECT id,production_id,title,category,starts_at,ends_at,location,required_slots,approval_required FROM volunteer_shifts WHERE id=:id FOR UPDATE');$s->execute(['id'=>$shiftId]);$before=$s->fetch();if(!$before)throw new RuntimeException('That volunteer shift no longer exists.');if((int)$before['production_id']!==(int)$production['id'])throw new RuntimeException('That shift belongs to a different production workspace.');$confirmed=$db->prepare("SELECT COUNT(*) FROM volunteer_shift_signups WHERE shift_id=:shift AND status IN ('signed_up','checked_in','completed')");$confirmed->execute(['shift'=>$shiftId]);$count=(int)$confirmed->fetchColumn();if($requiredSlots<$count)throw new RuntimeException('Capacity cannot be lower than the '.$count.' currently confirmed volunteers.');$db->prepare('UPDATE volunteer_shifts SET title=:title,category=:category,starts_at=:starts,ends_at=:ends,location=:location,required_slots=:slots,approval_required=:approval WHERE id=:id')->execute(['title'=>$title,'category'=>$category,'starts'=>$startsAt->format('Y-m-d H:i:s'),'ends'=>$endsAt->format('Y-m-d H:i:s'),'location'=>$location,'slots'=>$requiredSlots,'approval'=>$approvalRequired,'id'=>$shiftId]);}else{$db->prepare('INSERT INTO volunteer_shifts (production_id,title,category,starts_at,ends_at,location,required_slots,approval_required) VALUES (:production,:title,:category,:starts,:ends,:location,:slots,:approval)')->execute(['production'=>(int)$production['id'],'title'=>$title,'category'=>$category,'starts'=>$startsAt->format('Y-m-d H:i:s'),'ends'=>$endsAt->format('Y-m-d H:i:s'),'location'=>$location,'slots'=>$requiredSlots,'approval'=>$approvalRequired]);$shiftId=(int)$db->lastInsertId();}
            $db->prepare('DELETE FROM volunteer_shift_requirements WHERE shift_id=:shift')->execute(['shift'=>$shiftId]);if($requirements){$link=$db->prepare('INSERT INTO volunteer_shift_requirements (shift_id,requirement_id) VALUES (:shift,:requirement)');foreach($requirements as $requirementId)$link->execute(['shift'=>$shiftId,'requirement'=>$requirementId]);}
            self::audit($db,(int)$actor['id'],$before?'volunteer.shift_updated':'volunteer.shift_created','volunteer_shift',$shiftId,$before?'Updated volunteer shift configuration.':'Created volunteer shift.',['production_id'=>(int)$production['id'],'before'=>$before?:null,'after'=>['title'=>$title,'category'=>$category,'starts_at'=>$startsAt->format('Y-m-d H:i:s'),'ends_at'=>$endsAt->format('Y-m-d H:i:s'),'location'=>$location,'required_slots'=>$requiredSlots,'approval_required'=>(bool)$approvalRequired,'requirement_ids'=>$requirements]]);$db->commit();return $shiftId;
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The volunteer shift could not be saved.');}
    }

    private static function updateRosterStatus(PDO $db,array $actor,int $signupId,int $shiftId,string $status):void
    {
        $allowed=['signed_up','checked_in','completed','no_show','cancelled'];if($signupId<1||$shiftId<1||!in_array($status,$allowed,true))throw new RuntimeException('Choose a valid roster status.');$production=ProductionContext::selected($db,$actor);if(!$production)throw new RuntimeException('Select an active production before changing a volunteer roster.');
        $db->beginTransaction();try{$s=$db->prepare("SELECT s.id,s.shift_id,s.user_id,s.status,vs.title,vs.production_id,CONCAT(u.first_name,' ',u.last_name) volunteer_name FROM volunteer_shift_signups s JOIN volunteer_shifts vs ON vs.id=s.shift_id JOIN users u ON u.id=s.user_id WHERE s.id=:id FOR UPDATE");$s->execute(['id'=>$signupId]);$signup=$s->fetch();if(!$signup||(int)$signup['shift_id']!==$shiftId)throw new RuntimeException('That roster entry no longer exists.');if((int)$signup['production_id']!==(int)$production['id'])throw new RuntimeException('That roster entry belongs to a different production workspace.');if($signup['status']===$status){$db->commit();return;}$db->prepare('UPDATE volunteer_shift_signups SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$signupId]);self::audit($db,(int)$actor['id'],'volunteer.roster_status_changed','volunteer_shift_signup',$signupId,'Updated volunteer shift roster status.',['production_id'=>(int)$signup['production_id'],'shift_id'=>(int)$signup['shift_id'],'shift_title'=>$signup['title'],'volunteer_user_id'=>(int)$signup['user_id'],'volunteer_name'=>$signup['volunteer_name'],'before'=>$signup['status'],'after'=>$status]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The roster status could not be updated.');}
    }

    private static function requirements(PDO $db):array{return $db->query('SELECT id,name,category,expires FROM volunteer_requirements ORDER BY name')->fetchAll();}
    private static function shifts(PDO $db,int $productionId):array{if($productionId<1)return[];$s=$db->prepare("SELECT vs.id,vs.title,vs.category,vs.starts_at,vs.ends_at,vs.location,vs.required_slots,vs.approval_required,COALESCE(cap.confirmed,0) confirmed,COALESCE(req.requirement_count,0) requirement_count,COALESCE(pend.pending_requests,0) pending_requests FROM volunteer_shifts vs LEFT JOIN (SELECT shift_id,COUNT(*) confirmed FROM volunteer_shift_signups WHERE status IN ('signed_up','checked_in','completed') GROUP BY shift_id) cap ON cap.shift_id=vs.id LEFT JOIN (SELECT shift_id,COUNT(*) requirement_count FROM volunteer_shift_requirements GROUP BY shift_id) req ON req.shift_id=vs.id LEFT JOIN (SELECT shift_id,COUNT(*) pending_requests FROM volunteer_shift_approval_requests WHERE status='pending' GROUP BY shift_id) pend ON pend.shift_id=vs.id WHERE vs.production_id=:production ORDER BY vs.starts_at,vs.id");$s->execute(['production'=>$productionId]);return $s->fetchAll();}
    private static function shift(PDO $db,int $shiftId,int $productionId):?array{if($shiftId<1||$productionId<1)return null;$s=$db->prepare('SELECT vs.*,p.title production_title FROM volunteer_shifts vs LEFT JOIN productions p ON p.id=vs.production_id WHERE vs.id=:id AND vs.production_id=:production LIMIT 1');$s->execute(['id'=>$shiftId,'production'=>$productionId]);$shift=$s->fetch();if(!$shift)return null;$req=$db->prepare('SELECT vr.id,vr.name,vr.category FROM volunteer_shift_requirements vsr JOIN volunteer_requirements vr ON vr.id=vsr.requirement_id WHERE vsr.shift_id=:shift ORDER BY vr.name');$req->execute(['shift'=>$shiftId]);$shift['requirements']=$req->fetchAll();$shift['requirement_ids']=array_map(static fn(array $row):int=>(int)$row['id'],$shift['requirements']);$roster=$db->prepare("SELECT s.id signup_id,s.user_id,s.status,s.created_at,CONCAT(u.first_name,' ',u.last_name) name,u.display_role,(SELECT COUNT(*) FROM volunteer_shift_approval_requests r WHERE r.shift_id=s.shift_id AND r.user_id=s.user_id AND r.status='approved') approved_request FROM volunteer_shift_signups s JOIN users u ON u.id=s.user_id WHERE s.shift_id=:shift ORDER BY FIELD(s.status,'checked_in','signed_up','completed','no_show','cancelled','waitlisted'),u.last_name,u.first_name");$roster->execute(['shift'=>$shiftId]);$shift['roster']=$roster->fetchAll();$pending=$db->prepare("SELECT r.id,r.user_id,r.request_note,r.requested_at,CONCAT(u.first_name,' ',u.last_name) name FROM volunteer_shift_approval_requests r JOIN users u ON u.id=r.user_id WHERE r.shift_id=:shift AND r.status='pending' ORDER BY r.requested_at");$pending->execute(['shift'=>$shiftId]);$shift['pending_requests']=$pending->fetchAll();return $shift;}
    private static function audit(PDO $db,int $actorId,string $eventType,string $subjectType,int $subjectId,string $summary,array $metadata):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:metadata)');$s->execute(['actor'=>$actorId,'event'=>$eventType,'type'=>$subjectType,'id'=>$subjectId,'summary'=>$summary,'metadata'=>json_encode($metadata,JSON_THROW_ON_ERROR)]);}
    private static function parseLocalDateTime(string $value,string $label):DateTimeImmutable{$date=DateTimeImmutable::createFromFormat('Y-m-d\\TH:i',trim($value));if(!$date)throw new RuntimeException($label.' is required.');return $date;}

    private static function page(PDO $db,string $route,string $basePath,array $user,?array $production,array $requirements,?array $shift):never
    {
        $url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=$_SESSION['volunteer_shift_admin_flash']??$_SESSION['production_context_flash']??null;unset($_SESSION['volunteer_shift_admin_flash'],$_SESSION['production_context_flash']);$shifts=self::shifts($db,$production?(int)$production['id']:0);$defaultStart=(new DateTimeImmutable('next saturday 10:00'))->format('Y-m-d\\TH:i');$defaultEnd=(new DateTimeImmutable('next saturday 14:00'))->format('Y-m-d\\TH:i');$editing=$route==='/admin/volunteer-shifts/view'&&$shift;$selectedRequirements=$editing?$shift['requirement_ids']:[];
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Volunteer Operations · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/volunteer-shift-management.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Operations',$editing?$shift['title']:($route==='/admin/volunteer-shifts/new'?'New volunteer shift':'Volunteer Operations'),$basePath,[['label'=>'Shifts','href'=>'/admin/volunteer-shifts','active'=>$route==='/admin/volunteer-shifts'],['label'=>'Requirements & training','href'=>'/admin/volunteer-development','active'=>false],['label'=>'Approval queue','href'=>'/admin/volunteer-approvals','active'=>false],['label'=>'Verification','href'=>'/admin/volunteer-verification','active'=>false]]);?><div class="vsm-page"><?php if($flash):?><div class="vsm-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?>
        <?php if(!$production):?><section class="vsm-empty"><small>NO ACTIVE PRODUCTION</small><h2>Volunteer shifts need a production workspace.</h2><p>Activate a production or select another active show before creating staffing opportunities.</p><a class="button" href="<?=$url('/admin/productions')?>">Manage productions</a></section>
        <?php elseif($route==='/admin/volunteer-shifts'):?><section class="vsm-hero"><div><small><?=$e(strtoupper($production['title']))?> · WORKING PRODUCTION</small><h2>Staff the work behind the show.</h2><p>Create shifts, attach eligibility rules, and manage coverage for the selected production.</p></div><a class="button" href="<?=$url('/admin/volunteer-shifts/new')?>">Create shift</a></section><div class="vsm-list"><?php if(!$shifts):?><div class="vsm-empty"><b>No volunteer shifts yet.</b></div><?php else:foreach($shifts as $row):$open=max((int)$row['required_slots']-(int)$row['confirmed'],0);?><a href="<?=$url('/admin/volunteer-shifts/view?id='.(int)$row['id'])?>" class="vsm-row"><div class="vsm-date"><b><?=$e(date('M',strtotime($row['starts_at'])))?></b><span><?=$e(date('j',strtotime($row['starts_at'])))?></span></div><div><small><?=$e(strtoupper($row['category']))?><?=(bool)$row['approval_required']?' · APPROVAL REQUIRED':''?></small><h3><?=$e($row['title'])?></h3><p><?=$e(date('g:i A',strtotime($row['starts_at'])))?>–<?=$e(date('g:i A',strtotime($row['ends_at'])))?> · <?=$e($row['location'])?></p><span><?=(int)$row['requirement_count']?> eligibility rule<?=((int)$row['requirement_count']===1?'':'s')?> · <?=(int)$row['pending_requests']?> pending</span></div><div class="vsm-cover"><b><?=(int)$row['confirmed']?>/<?=(int)$row['required_slots']?></b><span><?=$open?> open</span><em>Manage →</em></div></a><?php endforeach;endif;?></div>
        <?php else:?><section class="vsm-head"><div><small><?=$e(strtoupper($production['title']))?> · WORKING PRODUCTION</small><h2><?=$editing?$e($shift['title']):'Create volunteer shift'?></h2></div><a href="<?=$url('/admin/volunteer-shifts')?>">← All shifts</a></section><?php if($route==='/admin/volunteer-shifts/view'&&!$shift):?><section class="vsm-empty"><b>Shift not found in this production</b></section><?php else:?><div class="vsm-layout"><form class="vsm-form" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_shift_admin_csrf'])?>"><input type="hidden" name="action" value="<?=$editing?'update':'create'?>"><?php if($editing):?><input type="hidden" name="shift_id" value="<?=(int)$shift['id']?>"><?php endif;?><label>Shift title<input name="title" maxlength="190" required value="<?=$editing?$e($shift['title']):''?>"></label><div class="vsm-pair"><label>Category<input name="category" maxlength="100" required value="<?=$editing?$e($shift['category']):''?>"></label><label>Location<input name="location" maxlength="190" required value="<?=$editing?$e($shift['location']):''?>"></label></div><div class="vsm-pair"><label>Start<input type="datetime-local" name="starts_at" required value="<?=$editing?$e(date('Y-m-d\\TH:i',strtotime($shift['starts_at']))):$e($defaultStart)?>"></label><label>End<input type="datetime-local" name="ends_at" required value="<?=$editing?$e(date('Y-m-d\\TH:i',strtotime($shift['ends_at']))):$e($defaultEnd)?>"></label></div><label>Required volunteers<input type="number" name="required_slots" min="1" max="500" required value="<?=$editing?(int)$shift['required_slots']:1?>"></label><label class="vsm-check"><input type="checkbox" name="approval_required" value="1"<?=$editing&&(bool)$shift['approval_required']?' checked':''?>><span><b>Coordinator approval required</b></span></label><fieldset><legend>Eligibility rules</legend><p>Select every requirement a volunteer must have current before Connect permits signup. For example, a Box Office shift can require Box Office Training plus a current Background Check.</p><?php if(!$requirements):?><p><a href="<?=$url('/admin/volunteer-development')?>">Define volunteer requirements first →</a></p><?php endif;?><?php foreach($requirements as $requirement):?><label class="vsm-check"><input type="checkbox" name="requirement_ids[]" value="<?=(int)$requirement['id']?>"<?=in_array((int)$requirement['id'],$selectedRequirements,true)?' checked':''?>><span><b><?=$e($requirement['name'])?></b><small><?=$e(ucfirst(str_replace('_',' ',$requirement['category'])))?><?=$requirement['expires']?' · expiration enforced':''?></small></span></label><?php endforeach;?><p><a href="<?=$url('/admin/volunteer-development')?>">Manage requirement definitions & training →</a></p></fieldset><footer><a href="<?=$url('/admin/volunteer-shifts')?>">Cancel</a><button class="button" type="submit"><?=$editing?'Save shift':'Create shift'?></button></footer></form><aside class="vsm-side"><?php if(!$editing):?><small>ELIGIBILITY ENGINE</small><h3>Rules are enforced at signup.</h3><p>Every selected requirement is checked against the volunteer’s current approved credentials. Missing or expired requirements block signup automatically.</p><?php else:$confirmed=count(array_filter($shift['roster'],static fn(array $r):bool=>in_array($r['status'],['signed_up','checked_in','completed'],true)));?><small>LIVE COVERAGE</small><b class="vsm-big"><?=$confirmed?>/<?=(int)$shift['required_slots']?></b><h3>confirmed volunteers</h3><p><?=count($shift['pending_requests'])?> approval requests waiting.</p><?php if($shift['pending_requests']):?><a class="button secondary full" href="<?=$url('/admin/volunteer-approvals')?>">Review approvals</a><?php endif;?><?php endif;?></aside></div><?php if($editing):?><section class="vsm-roster"><header><div><small>CONFIRMED ROSTER</small><h3>Shift staffing</h3></div></header><?php if(!$shift['roster']):?><div class="vsm-empty compact"><b>No confirmed volunteers yet.</b></div><?php else:?><div class="vsm-roster-list"><?php foreach($shift['roster'] as $member):?><article><div><b><?=$e($member['name'])?></b><small><?=$e($member['display_role'])?> · <?=$e(str_replace('_',' ',$member['status']))?></small></div><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_shift_admin_csrf'])?>"><input type="hidden" name="action" value="roster_status"><input type="hidden" name="shift_id" value="<?=(int)$shift['id']?>"><input type="hidden" name="signup_id" value="<?=(int)$member['signup_id']?>"><select name="status"><?php foreach(['signed_up'=>'Confirmed','checked_in'=>'Checked in','completed'=>'Completed','no_show'=>'No show','cancelled'=>'Cancelled'] as $value=>$label):?><option value="<?=$e($value)?>"<?=$member['status']===$value?' selected':''?>><?=$e($label)?></option><?php endforeach;?></select><button type="submit">Update</button></form></article><?php endforeach;?></div><?php endif;?></section><?php endif;?><?php endif;?><?php endif;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function forbidden(string $basePath,array $user):never{http_response_code(403);header('Content-Type:text/plain; charset=utf-8');echo 'Staff only';exit;}
    private static function flash(string $type,string $message):void{$_SESSION['volunteer_shift_admin_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}